import * as console from "std/console"
export function test(): null {
  let acc: string = "";
  let count: int = 0;
  for (let c: string of "a😀b") {
    acc = acc + c;
    count = count + 1;
  }
  console.log(acc);
  if (count !== 3) { console.log("bad-count"); return; }
  if (acc !== "a😀b") { console.log("bad-acc"); return; }
  console.log("scalar-forof-ok");
}

import * as str from "std/string"
export function test(): int {
  let ascii: int = str.length("hello");
  let empty: int = str.length("");
  let accented: int = str.length("héllo");
  let sup: int = str.length("a😀b");
  return ascii * 1000 + empty * 100 + accented * 10 + (sup - 3);
}

import * as str from "std/string"
export function test(): string {
  let first: string = str.substring("a😀b", 0, 1);
  let mid: string = str.substring("a😀b", 1, 2);
  let last: string = str.substring("a😀b", 2, 3);
  let whole: string = str.substring("a😀b", 0, 3);
  return first + "|" + mid + "|" + last + "|" + whole;
}

import * as str from "std/string"
export function test(): int {
  let parts: string[] = str.split("😀b", "");
  if (parts.length !== 2) { return 0; }
  if (parts[0] !== "😀") { return 0; }
  if (parts[1] !== "b") { return 0; }
  return 7;
}

